TLM.f("Tempora/Adv3-3",{"officium":"Feria IV Quattuor Temporum in Adventu","rule":["Oratio Dominica","no Gloria","no Credo","LectioL1","Suffr=Maria1;Ecclesiæ,Papa;;"],"ruleInherited":["no Gloria","Credo","Suffr=Maria1;Ecclesiæ,Papa;;"],"fallback":"Tempora/Adv3-0","from":{"GradualeF":"Tempora/Adv3-0"},"sections":{"Introitus":[{"k":"ref","la":"Is 45:8"},{"k":"text","la":"Roráte, cœli, désuper, et nubes pluant justum: aperiátur terra, et gérminet Salvatórem"},{"k":"ref","la":"Ps 18:2"},{"k":"text","la":"Cœli enárrant glóriam Dei: et ópera mánuum ejus annúntiat firmaméntum."},{"k":"macro","name":"Gloria"},{"k":"text","la":"Roráte, cœli, désuper, et nubes pluant justum: aperiátur terra, et gérminet Salvatórem"}],"Oratio":[{"k":"text","la":"Præsta, quǽsumus, omnípotens Deus: ut redemptiónis nostræ ventúra sollémnitas et præséntis nobis vitæ subsídia cónferat, et ætérnæ beatitúdinis prǽmia largiátur."},{"k":"macro","name":"Per Dominum"}],"Lectio":[{"k":"text","la":"Lectio Isaíæ Prophétæ"},{"k":"ref","la":"Is 7:10-15"},{"k":"text","la":"In diébus illis: Locútus est Dóminus ad Achaz, dicens: Pete tibi signum a Dómino, Deo tuo, in profúndum inférni, sive in excélsum supra. Et dixit Achaz: Non petam et non tentábo Dóminum. Et dixit: Audíte ergo, domus David: Numquid parum vobis est, moléstos esse homínibus, quia molesti estis et Deo meo? Propter hoc dabit Dóminus ipse vobis signum. Ecce, Virgo concípiet et páriet fílium, et vocábitur nomen ejus Emmánuel. Butýrum et mel cómedet, ut sciat reprobare malum et elígere bonum."}],"Graduale":[{"k":"ref","la":"Ps 144:18; 144:21"},{"k":"text","la":"Prope est Dóminus ómnibus invocántibus eum: ómnibus qui ínvocant eum in veritáte."},{"k":"text","la":"Laudem Dómini loquétur os meum: et benedícat omnis caro nomen sanctum ejus.","mark":"V"}],"GradualeF":[{"k":"ref","la":"Ps 79:2; 79:3; 79:2"},{"k":"text","la":"Qui sedes, Dómine, super Chérubim, éxcita poténtiam tuam, et veni."},{"k":"text","la":"Qui regis Israël, inténde: qui dedúcis, velut ovem, Joseph.","mark":"V"}],"Evangelium":[{"k":"text","la":"Sequéntia ✠ sancti Evangélii secundum Lucam"},{"k":"ref","la":"Luc 1:26-38"},{"k":"text","la":"In illo tempore: Missus est Angelus Gábriel a Deo in civitatem Galilǽæ, cui nomen Názareth, ad Vírginem desponsátam viro, cui nomen erat Joseph, de domo David, et nomen Vírginis María. Et ingréssus Angelus ad eam, dixit: Ave, grátia plena; Dóminus tecum: benedícta tu in muliéribus. Quæ cum audísset, turbáta est in sermóne ejus: et cogitábat, qualis esset ista salutátio. Et ait Angelus ei: Ne tímeas, María, invenísti enim grátiam apud Deum: ecce, concípies in útero, et páries fílium, et vocábis nomen ejus Jesum. Hic erit magnus, et Fílius Altíssimi vocábitur, et dabit illi Dóminus Deus sedem David, patris ejus: et regnábit in domo Jacob in ætérnum, et regni ejus non erit finis. Dixit autem María ad Angelum: Quómodo fiet istud, quóniam virum non cognósco? Et respóndens Angelus, dixit ei: Spíritus Sanctus supervéniet in te, et virtus Altíssimi obumbrábit tibi. Ideóque et quod nascétur ex te Sanctum, vocábitur Fílius Dei. Et ecce, Elísabeth, cognáta tua, et ipsa concépit fílium in senectúte sua: et hic mensis sextus est illi, quæ vocátur stérilis: quia non erit impossíbile apud Deum omne verbum. Dixit autem María: Ecce ancílla Dómini, fiat mihi secúndum verbum tuum."}],"Offertorium":[{"k":"ref","la":"Is 35:4"},{"k":"text","la":"Confortámini, et jam nolite timére: ecce enim, Deus noster retríbuet judícium: ipse véniet, et salvos nos fáciet."}],"Secreta":[{"k":"text","la":"Acépta tibi sint, quǽsumus, Dómine, nostra jejúnia: quæ et expiándo nos tua grátia dignos effíciant, et ad sempiterna promíssa perdúcant."},{"k":"macro","name":"Per Dominum"}],"Communio":[{"k":"ref","la":"Is 7:14"},{"k":"text","la":"Ecce, Virgo concípiet et páriet fílium: et vocábitur nomen ejus Emmánuel."}],"Postcommunio":[{"k":"text","la":"Salutáris tui, Dómine, munere satiáti, súpplices deprecámur: ut, cujus lætámur gustu, renovémur efféctu."},{"k":"macro","name":"Per Dominum"}],"LectioL1":[{"k":"text","la":"Léctio Isaíæ Prophétæ"},{"k":"ref","la":"Is 2:2-5"},{"k":"text","la":"In diébus illis: Dixit Isaias Prophéta: Erit in novíssimis diébus præparátus mons domus Dómini in vértice móntium, et elevábitur super colles, et fluent ad eum omnes gentes. Et ibunt pópuli multi, et dicent: Veníte et ascendámus ad montem Dómini, et ad domum Dei Jacob, et docébit nos vias suas, et ambulábimus in sémitis ejus: quia de Sion exíbit lex, et verbum Dómini de Jerúsalem. Et judicábit gentes, et árguet pópulos multos: et conflábunt gládios suos in vómeres, et lánceas suas in falces. Non levábit gens contra gentem gládium: nec exercebúntur ultra ad prǽlium. Domus Jacob, veníte, et ambulémus in lúmine Dómini, Dei nostri."},{"k":"macro","name":"Deo gratias"}],"GradualeL1":[{"k":"ref","la":"Ps 23:7; 23:3; 23:4"},{"k":"text","la":"Tóllite portas, principes, vestras: et elevámini, portæ æternáles: et introíbit Rex glóriæ."},{"k":"text","la":"Quis ascéndet in montem Dómini? aut quis stabit in loco sancto ejus ? Innocens mánibus et mundo corde.","mark":"V"}],"OratioL1":[{"k":"text","la":"Festína, quǽsumus, Dómine, ne tardáveris, et auxílium nobis supérnæ virtútis impénde: ut advéntus tui consolatiónibus sublevéntur, qui in tua pietáte confídunt:"},{"k":"macro","name":"Qui vivis"}]},"hr":{"f5880ffb7ba7465a":{"t":"Iz, 45, 8, Ps 18, 2\n(Iz 45, 8) Rosite, nebesa, s visine! Oblaci, daždite Pravednika! Neka se otvori zemlja i neka iz nje nikne Spasitelj! (Ps 18, 2) Nebesa pripovijedaju slavu Božju i nebeski svod navješćuje djelo njegovih ruku.\n<i>Slava Ocu, i Sinu, i Duhu Svetomu. Kako bijaše na početku, tako i sada i vazda i u vijeke vjekova. Amen</i>.\n(Iz 45, 8) Rosite, nebesa, s visine! Oblaci, daždite Pravednika! Neka se otvori zemlja i neka iz nje nikne Spasitelj!","v":"isai → ∅; isai → ∅","kn":"(Izai. 45, 8). Rosite, nebesa, s visine i oblaci neka dažde Pravednika! Neka se otvori zemlja i neka iz nje nikne Spasitelj! (Ps. 18, 2). Nebesa pričaju slavu Božju i djela ruku njegovih naviješta svod nebeski. Slava Ocu . . . Rosite . . .","knRef":"Kniewald 1942, str. 52–53 (snimka 27) (OCR)"},"2e4dc803384a779c":{"t":"<i>Pomolimo se</i>.\n<i>Prignimo koljena. - Ustanite</i>.\nPodaj, molimo, svemogući Bože, da nam skori blagdan našeg otkupljenja donese pomoć u sadašnjem životu i udijeli vječnu nagradu.\n<i>Po Gospodinu našemu Isusu Kristu, Sinu tvome: Koji s tobom živi i kraljuje u jedinstvu Duha Svetoga, Bog: po sve vijeke vjekova</i>.","kn":"Podaj, molimO', svemogući Bože, da nam iduća svetkovina udijeli i pomoć u sadanjem životu i nagradu vječnog blaženstva, po G. n. I. K.","knRef":"Kniewald 1942, str. 42–43 (snimka 22) (OCR)"},"465ae490da585a03":{"t":"Iz 2, 2-5\nČitanje Izaije proroka. U one dane reče Izaija prorok: U posljednje vrijeme stajat će izabrana gora za kuću Gospodnju na vrhuncima planina, visoko iznad svih bregova. K njoj će hrliti svi narodi. Mnoga će plemena dolaziti i govoriti: Dođite i popnimo se na goru Gospodnju, u kuću Boga Jakovljeva. On će nas poučiti svojim putovima i ići ćemo njegovim stazama. Sa Siona će, naime, izići zakon i riječ Gospodnja iz Jeruzalema. Sudit će neznabošcima i krojiti pravdu mnogim narodima. Oni će prekovati svoje mačeve u plugove i svoja koplja u srpove. I više neće dizati mač narod protiv naroda, niti će se više ikada pripremati za rat. Kućo Jakovljeva, dođite, idimo u svjetlosti Gospodina Boga našega.","kn":"Čitanje Izai je proroka (2, 2-5). U onim danima reče Izaija prorok: U posljednje vrijeme stajat će brijeg doma Gospodnjega divan, povrh .svih bregova. On će nadvisivati sve brežuljke i k njemu će dolaziti svi narodi. I mnogi će narodi govoriti: Pođimo i uspnimo se na brijeg Gospodnji i k domu Boga Jakovljeva. On će nas učiti svojim putovima i mi ćemo ići njegovim stazama. Jer iz Siona će izaći zakon i Riječ Božja iz Jeruzalernai. On će suditi pogane i pravdu reći mnogim narodima. I oni će prekovati svoje mačeve u plugove, a koplja u srpove. Ne će više narod protiv naroda, podizati mača., niti će se spremati za rat. O, dome Jakovljev, dajte, krečimo se u svijetlu Gospodina Boga našega!","knRef":"Kniewald 1942, str. 42–43 (snimka 22) (OCR)"},"57940b4a6710beae":{"t":"Ps 23, 7, Ps 23, 3-4\n(Ps 23, 7) Podignite, knezovi, vrata svoja! Uzdignite se, vrata vječna! Unići će Kralj slave. (Ps 23, 3-4) Tko će uzaći na goru Gospodnju? Tko će stati na svetom mjestu njegovu? Onaj koji je nevinih ruku i čista srca.","kn":"(Ps. 23, 7). Uzdignite, knezovi I vrata svoja; dignite se, vrata vječna: da uniđe Kralj I slave. Tko će uzaći na goru Gospodnju, ili tko će stati na svetom mjestu Njegovu? Onaj, u koga su ! nevine ruke i čisto srce.","knRef":"Kniewald 1942, str. 36–37 (snimka 19) (OCR)"},"41fcdd5f3722416f":{"t":"<i>Pomolimo se</i>.\nPožuri i nemoj kasniti, molimo, Gospodine, i daj nam pomoć višnje moći, da oni koji se uzdaju u tvoju blagost budu uzdignuti utjehom tvoga dolaska:\n<i>koji živiš i kraljuješ s Bogom Ocem u jedinstvu Duha Svetoga, Bog: po sve vijeke vjekova</i>."},"01070ac82bdfed7f":{"t":"Iz 7, 10-15\nČitanje Izaije proroka. U one dane reče Gospodin Ahazu: Traži od Gospodina, Boga svojega, znak dolje u dubini ili gore u visini. Ahaz odgovori: Neću tražiti i neću iskušavati Gospodina. Tada reče (Izaija): Čujte sada, dome Davidov: Zar vam je malo, što ste teški ljudima, pa još odbijate i moga Boga? Zato će vam sam Gospodin dati znak: Evo, djevica će začeti i roditi sina i dat će mu ime Emanuel. On će se hraniti medom i mlijekom, dok ne sazna odbacivati zlo, a odabirati dobro.","kn":"Čitanje proroka Izaije (7, 10-15). U one dane reče Gospodin Ahazu: Traži od Gospodina svoga Boga znak za sebe, ili odozdo iz ponora ili odozgo s visine. Ahaz odgovori: Ne ću tražiti niti ću kušati Gospodina. Nato reče: Čujte vi iz kuće Davidove: Zar vam je malo, što dosađujete ljudima, pa dosađujete i momu Bogu? Zato će vam sam Gospodin dati znak; Evo, djevica će začeti i roditi sina i dat će mu ime Emanuel.^ Jesti će maslo 1 med, da zna odbaciti zlo, a izabrati dobro.","knRef":"Kniewald 1942, str. 532–533 (snimka 267) (OCR)"},"5fcd31d3abd4fd13":{"t":"Ps 144, 18 i 21\nGospodin je blizu svima koji ga zazivaju, svima koji ga zazivaju iskreno. Neka moja usta navješćuju hvalu Gospodnju i svaki čovjek neka blagoslivlja sveto ime njegovo.","kn":"(Ps. 144, 18, 21). Blizu je Gospodin svima, koji ga zazivaju, koji ga zazivaju u Istini. Usta će moja zboriti hvalu Božju i svaki čovjek neka blagosiva njegovo sveto ime.","knRef":"Kniewald 1942, str. 52–53 (snimka 27) (OCR)"},"b7fcb7fcf7056bff":{"t":"Lk 1, 26-38\nSlijedi sveto Evanđelje po Luki. U ono vrijeme: Posla Bog anđela Gabrijela u galilejski grad Nazaret k djevici Mariji, koja je bila zaručena s Davidovim potomkom Josipom. Anđeo uđe k njoj i reče: Zdravo, milosti puna, Gospodin s tobom, blagoslovljena ti među ženama! Kad je ona to čula, uplaši se i razmišljala je što taj pozdrav znači. Anđeo joj reče: Nemoj se bojati, Marijo, jer si našla milost u Boga: Evo, začet ćeš i roditi sina i dat ćeš mu ime Isus. On će biti velik i zvat će se Sin Svevišnjega. Gospodin će mu dati prijestolje njegova oca Davida, i vladat će Jakovljevom kućom dovijeka i njegovu kraljevstvu neće biti svršetka. Marija reče anđelu: Kako će to biti kad ne poznam muža? Anđeo joj odgovori: Duh će Sveti sići na te i sila će te Svevišnjega osjeniti. Zato će se ono Sveto, što ćeš ti roditi, zvati Sin Božji. A evo, i Elizabeta, tvoja rođakinja, i ona je začela sina u svojoj starosti, i njoj koju zovu nerotkinjom ovo je šesti mjesec, jer u Boga nije ništa nemoguće. Marija na to reče: Evo službenice Gospodnje, neka mi bude po riječi tvojoj.","kn":"t Slijedi sveto evanđelje po Luki (1, 26-38). U ono vrijeme posla Bog anđela Gabrijela u galilejski grad Nazaret k djevici zaručenoj s mužem, koji se zvaO' Josip iz kuće Davidove, a djevica se zvala Marija. Kad je anđeo k njoj ušao, reče: Zdravo milosti puna. Gospodin s tobom, blagoslovljena ti među ženama! Kad je ona to čula, uplaši se na ove riječi i razmišljala je, što znači taj pozdrav. A anđeo joj reče; Ne boj se, Marijo, jer si našla milost kod Bega: Evo, začet ćeš i roditi sina i dat ćeš mu ime Isus. On će biti velik i zvat će se Sin Svevišnjega. I Gospodin Bog dat će mu prijestolje Davida, njegova oca, i vladat će nad Jakovljevim domom u vijeke, i njegovu kraljevstvu ne će biti kraja. Marija upita anđela: Kako će to biti, kad ja ne (poznam muža? Anđeo joj odgovori: Duh Sveti doći će nad tebe i osjenit će te sila Svevišnjega; zato će i Sveto, koje ćeš ti roditi, biti Sin Božji. I tvoja je rođakinja Elizabeta začela Sv. Ivan Damascenski 27. III. sina u svojoj starosti, i njoj, koja je nerotkinja, ovo je šesti mjesec; jer Bogu nije ništa nemoguće. Na to Marija reče: Evo službenice Gospodnje, neka mi bude po tvojoj riječi.","knRef":"Kniewald 1942, str. 534–535 (snimka 268) (OCR)"},"8b183685bf701fdd":{"t":"Iz 35, 4\nBudite hrabri i ne bojte se! Evo Bog će naš suditi. On sam će doći i spasit će nas.","kn":"(Isai, 35, 4). Ohrabrite se i ne bojte se više: jer Bog će naš suditi i doći će, da nas spasi!","knRef":"Kniewald 1942, str. 44–45 (snimka 23) (OCR)"},"a2f630bda2f7ed40":{"t":"Neka ti, molimo, Gospodine, budu ugodni naši postovi, da po njima okajemo svoje grijehe i zaslužimo tvoju milost te prispijemo do vječnih obećanja.\n<i>Po Gospodinu našemu Isusu Kristu, Sinu tvome: Koji s tobom živi i kraljuje u jedinstvu Duha Svetoga, Bog: po sve vijeke vjekova</i>.","kn":"Molimo, Gospodine, da Tebi budu, prijatni naši postovi, a mi da njima okajemo svoje grijehe i postanemo vrijedni Tvoje milosti, te nas dovedu, do vječnih obećanja, po G. n. I. K..","knRef":"Kniewald 1942, str. 44–45 (snimka 23) (OCR)"},"404159d2e4df1ef4":{"t":"Uistinu je dostojno i pravedno, pravo i spasonosno, da vazda i svagdje zahvaljujemo tebi, Gospodine, sveti Oče, svemogući vječni Bože, po Kristu Gospodinu našemu. – Po njemu tvoje veličanstvo hvale anđeli, klanjaju se gospodstva i dršću vlasti. Nebesa i nebeske sile i blaženi serafini zajedničkim klicanjem slave. Daj, molimo, s njima i naše glase primi dok govorimo poniznim hvalospjevom:","kn":"Uistinu je dostojno i pravedno, pravo i spasonosno, da vazda i svagdje zahvaljujemo Tebi, Gospodine sveti. Oče svemogući, vječni Bože, po Kristu, Gospotdiniu našemu, po kome veličanstvo Tvoje hvale anđeli, klanjaju Ti se gospodstva, tresu se vlasti. Nebesa Te i nebeske moći i blaženi serafini, zadružnim klicanjem zajedno slave. Zapovijedi, molimo, da se i naši glasovi združe s njihovima, smjernim isippvijedanjem govoreći:","knRef":"Kniewald 1942, str. 18–19 (snimka 10) (OCR)"},"11efe5bb9752667a":{"t":"Iz 7, 14\nEvo, Djevica će začeti i roditi Sina, i on će se zvati Emanuel.","kn":"(Izal. 7, 14). Evo, Djevica će začeti i rodit će Sina i zvat će se ime njegovo Emanuel.","knRef":"Kniewald 1942, str. 534–535 (snimka 268) (OCR)"},"ff1675cd1cc128fd":{"t":"<i>Pomolimo se</i>.\nNahranjeni tvojim spasonosnim darom ponizno te molimo, Gospodine, da nas obnovi djelovanje ovog otajstva koje radosno primamo.\n<i>Po Gospodinu našemu Isusu Kristu, Sinu tvome: Koji s tobom živi i kraljuje u jedinstvu Duha Svetoga, Bog: po sve vijeke vjekova</i>.","kn":"Nahranjeni darom Tvoga spasenja ponizno Te molimo. Gospodine, da nas obnovi djelovanje onoga, što uživamo š radošću, po G. n. I. K.","knRef":"Kniewald 1942, str. 44–45 (snimka 23) (OCR)"}}});
